import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type RetroLoadingBarProps = Record<string, any>;

const RetroLoadingBar: React.FC<RetroLoadingBarProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 5,
  pillColor = "#0000FF",
  accentColor = "#FFFFFF",
  textColor = "#FFFFFF",
  titleText = "Loading",
  segmentCount = 20,
  showPercentage = true,
  pulseAnimation = true,
}) => {
  useFontLoader(["Inter", "Roboto Mono"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color handling
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Animation drivers
  const totalFrames = durationInSeconds * fps;
  const progress = interpolate(frame, [0, totalFrames], [0, 100], {
    extrapolateRight: "clamp",
  });
  
  // Entrance animation (Spring Pop)
  const scale = spring({
    frame,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  // Calculate segments
  const activeSegments = Math.floor((progress / 100) * segmentCount);
  
  // Percentage counter
  const percentageValue = Math.floor(progress);

  // Dot animation for "Loading..."
  const dotCycle = Math.floor(frame / 15) % 4;
  const dots = ".".repeat(dotCycle);

  // Pulse effect for the pill container
  const pulse = pulseAnimation 
    ? interpolate(Math.sin(frame / 10), [-1, 1], [1, 1.02]) 
    : 1;

  // Dynamic Styles
  const containerStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    justifyContent: "center",
    alignItems: "center",
    width: width,
    height: height,
    fontFamily: "Inter, sans-serif",
    backgroundColor: finalBgColor,
  };

  const pillStyle: React.CSSProperties = {
    backgroundColor: pillColor,
    borderRadius: "100px", // High value for pill shape
    padding: "50px 70px",
    width: Math.min(800, width * 0.8),
    display: "flex",
    flexDirection: "column",
    gap: "20px",
    boxShadow: "0 10px 30px rgba(0,0,0,0.3)",
    transform: `scale(${scale * pulse})`,
    position: "relative",
  };

  const titleStyle: React.CSSProperties = {
    color: textColor,
    fontSize: "48px",
    fontWeight: 600,
    margin: 0,
    paddingLeft: "10px", // Slight alignment adjustment
    letterSpacing: "-0.02em",
  };

  const barContainerStyle: React.CSSProperties = {
    border: `4px solid ${accentColor}`,
    borderRadius: "16px",
    height: "80px",
    width: "100%",
    padding: "8px",
    display: "flex",
    gap: "6px",
    boxSizing: "border-box",
  };

  const segmentStyle = (isActive: boolean): React.CSSProperties => ({
    flex: 1,
    backgroundColor: isActive ? accentColor : "transparent",
    borderRadius: "6px",
    opacity: isActive ? 1 : 0.2,
    transition: "none", // Ensure frame-based animation only
  });

  const percentageStyle: React.CSSProperties = {
    position: "absolute",
    bottom: "-60px",
    right: "40px",
    color: "#e0ffe0", // Slight green tint as per retro reference usually has
    fontSize: "32px",
    fontFamily: "Roboto Mono, monospace",
    fontWeight: "bold",
    opacity: scale, // Fade in with the main container
  };

  return (
    <AbsoluteFill style={containerStyle}>
      <div style={pillStyle}>
        <h1 style={titleStyle}>
          {titleText}{dots}
        </h1>
        
        <div style={barContainerStyle}>
          {Array.from({ length: segmentCount }).map((_, index) => (
            <div
              key={index}
              style={segmentStyle(index < activeSegments)}
            />
          ))}
        </div>

        {showPercentage && (
          <div style={percentageStyle}>
            {percentageValue}%
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default RetroLoadingBar;